function esc(v){return String(v ?? '').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function lower(v){return String(v ?? '').toLowerCase();}
function upper(v){return String(v ?? '').trim().toUpperCase();}
function splitCSV(v){return String(v ?? '').split(',').map(x=>x.trim()).filter(Boolean);}
function normEntries(list){return (list||[]).map(e=>typeof e==='string'?e:(e&&(e.name||e.path||e.fileName))||'').filter(v=>typeof v==='string'&&v.length>0);}
function loadSession(){try{const d=JSON.parse(sessionStorage.getItem(DRAFT_KEY)||'{}');return d&&typeof d==='object'&&!Array.isArray(d)?d:{species:{},moves:{},settings:null,trainer:null};}catch(_){return{species:{},moves:{},settings:null,trainer:null};}}
function saveSession(d){try{sessionStorage.setItem(DRAFT_KEY,JSON.stringify(d||{}));}catch(_){}}
function ensureDraftShape(d){d=d&&typeof d==='object'?d:{};if(!d.species)d.species={};if(!d.moves)d.moves={};if(!('settings'in d))d.settings=null;if(!('trainer'in d))d.trainer=null;return d;}
function parseFields(lines,start,end){const out={};for(let i=start+1;i<end;i++){const s=String(lines[i]??'').trim();if(!s||s.startsWith('#')||!s.includes('='))continue;const p=s.indexOf('='),k=s.slice(0,p).trim(),v=s.slice(p+1).trim();if(k==='Evolution')out.Evolutions=out.Evolutions?`${out.Evolutions},${v}`:v;else out[k]=v;}return out;}
function parseSections(path,text){const lines=String(text??'').replace(/\r/g,'').split('\n'),starts=[],out=[];lines.forEach((l,i)=>{const m=String(l??'').trim().match(/^\[([^\]]+)\]$/);if(m)starts.push({i,header:m[1].trim()});});starts.forEach((s,n)=>{const end=n+1<starts.length?starts[n+1].i:lines.length,parts=s.header.split(',').map(x=>x.trim());out.push({path,header:s.header,id:upper(parts[0]),form:parts[1]?(parseInt(parts[1],10)||0):0,rawFields:parseFields(lines,s.i,end)});});return out;}
