async function layeredPbsPaths(ctx,pattern,baseName){
  let names=[];
  try{names=normEntries(await ctx.fs.listProjectDir('PBS'));}catch(_){}
  names=names.filter(n=>pattern.test(String(n).split(/[\\/]/).pop()||''));
  if(!names.some(n=>lower(String(n).split(/[\\/]/).pop())===lower(baseName))){
    try{if(await ctx.fs.projectExists(`PBS/${baseName}`))names.unshift(baseName);}catch(_){}
  }
  const clean=[...new Set(names.map(n=>String(n).startsWith('PBS/')?String(n):`PBS/${String(n)}`))];
  clean.sort((a,b)=>{
    const aa=lower(String(a).split(/[\\/]/).pop()),bb=lower(String(b).split(/[\\/]/).pop()),base=lower(baseName);
    if(aa===base&&bb!==base)return-1;
    if(bb===base&&aa!==base)return 1;
    return aa.localeCompare(bb);
  });
  return clean;
}

async function scanSpecies(ctx,cd){let names=[];try{names=normEntries(await ctx.fs.listProjectDir('PBS'));}catch(_){}names=names.filter(n=>/^pokemon.*\.txt$/i.test(String(n).split(/[\\/]/).pop()||''));if(!names.some(n=>lower(String(n).split(/[\\/]/).pop())==='pokemon.txt')){try{if(await ctx.fs.projectExists('PBS/pokemon.txt'))names.unshift('pokemon.txt');}catch(_){}}const clean=[...new Set(names.map(n=>String(n).startsWith('PBS/')?String(n):`PBS/${String(n)}`))];clean.sort((a,b)=>{const aa=lower(String(a).split(/[\\/]/).pop()),bb=lower(String(b).split(/[\\/]/).pop());if(aa==='pokemon.txt'&&bb!=='pokemon.txt')return-1;if(bb==='pokemon.txt'&&aa!=='pokemon.txt')return 1;return aa.localeCompare(bb);});const merged=new Map();let order=0;for(const path of clean){let rows=[];try{rows=parseSections(path,await ctx.fs.readProjectFile(path));}catch(_){}for(const e of rows){const k=`${e.id}|${e.form}`;let row=merged.get(k);if(!row){row={path:e.path,header:e.header,id:e.id,form:e.form,rawFields:{},sourceFiles:[],pbsOrder:order++};merged.set(k,row);}Object.assign(row.rawFields,e.rawFields||{});row.path=e.path;if(!row.sourceFiles.includes(e.path))row.sourceFiles.push(e.path);}}const all=[...merged.values()],bases=new Map(all.filter(e=>e.form===0).map(e=>[e.id,e]));return all.map(e=>{const base=bases.get(e.id),pbs=e.form>0&&base?{...base.rawFields,...e.rawFields}:{...e.rawFields};Object.keys(e.rawFields).forEach(k=>{if(e.form>0&&String(e.rawFields[k]??'').trim()===''&&base&&base.rawFields[k]!==undefined)pbs[k]=base.rawFields[k];});const bp=cd.species[e.id]||{},exact=e.form>0?`${e.id},${e.form}`:e.id,op=cd.species[exact]||{};return{...e,fields:{...pbs,...bp,...op},legacy:{goldenForm:String(op.GoldenForm??e.rawFields.GoldenForm??'').trim(),goldenType:String(op.GoldenType??e.rawFields.GoldenType??'').trim(),goldenTypeReplace:String(op.GoldenTypeReplace??e.rawFields.GoldenTypeReplace??'').trim()},changedex:Object.keys(bp).length>0||Object.keys(op).length>0};});}
async function scanTypes(ctx){const arr=[];try{parseSections('PBS/types.txt',await ctx.fs.readProjectFile('PBS/types.txt')).forEach(e=>{if(e.id)arr.push({id:e.id,name:String(e.rawFields.Name||e.id)});});}catch(_){}if(!arr.length)['NORMAL','FIRE','WATER','ELECTRIC','GRASS','ICE','FIGHTING','POISON','GROUND','FLYING','PSYCHIC','BUG','ROCK','GHOST','DRAGON','DARK','STEEL','FAIRY'].forEach(id=>arr.push({id,name:id}));return arr.sort((a,b)=>String(a.id).localeCompare(String(b.id)));}
async function scanMoves(ctx,cd){
  const map=new Map();let order=0;
  for(const path of await layeredPbsPaths(ctx,/^moves.*\.txt$/i,'moves.txt')){
    let rows=[];try{rows=parseSections(path,await ctx.fs.readProjectFile(path));}catch(_){}
    for(const e of rows){
      if(!e.id)continue;
      const prev=map.get(e.id)||{id:e.id,name:e.id,type:'',power:'',accuracy:'',category:'',functionCode:'',pbsOrder:order++,sourceFiles:[]};
      const f=e.rawFields||{};
      const next={...prev,id:e.id,name:String(f.Name??prev.name??e.id),type:upper(f.Type??prev.type??''),power:f.Power??prev.power??'',accuracy:f.Accuracy??prev.accuracy??'',category:f.Category??prev.category??'',functionCode:String(f.FunctionCode??prev.functionCode??'').trim()};
      if(!next.sourceFiles.includes(path))next.sourceFiles=[...next.sourceFiles,path];
      map.set(e.id,next);
    }
  }
  Object.entries(cd.moves||{}).forEach(([id,p])=>{
    const key=upper(id);if(!key)return;
    const b=map.get(key)||{id:key,name:key,type:'',power:'',accuracy:'',category:'',functionCode:'',pbsOrder:order++,sourceFiles:[]},m={...b,...(p||{})};
    map.set(key,{...b,id:key,name:String(m.Name||m.name||key),type:upper(m.Type||m.type||''),power:m.Power??m.power??'',accuracy:m.Accuracy??m.accuracy??'',category:m.Category??m.category??'',functionCode:String(m.FunctionCode??m.functionCode??b.functionCode??'').trim(),changedex:true});
  });
  return map;
}
