function statsFromFields(f){const p=splitCSV(f.BaseStats).map(n=>Number(n)||0);return{HP:p[0]||0,ATTACK:p[1]||0,DEFENSE:p[2]||0,SPEED:p[3]||0,SPECIAL_ATTACK:p[4]||0,SPECIAL_DEFENSE:p[5]||0};}
