    body.innerHTML=`<div class="gss-catalog-hero"><div class="gss-catalog-hero-top"><div><h2>Lista Áurea</h2><p>Biblioteca visual de todos los Golden Moves definidos. Ordena, filtra y abre cualquier entrada directamente en su editor por Pokémon.</p></div><div class="gss-sp"></div><span class="gss-badge gold">${rows.length} / ${total} visibles</span></div><div class="gss-catalog-tools"><input class="gss-search" data-gsearch placeholder="Buscar Pokémon, move, tipo..." value="${esc(st.goldenSearch)}"><select class="gss-select" data-gtype>${typeOpts(st.goldenType,'Todos los tipos')}</select><select class="gss-select" data-gsort><option value="pokemon" ${st.goldenSort==='pokemon'?'selected':''}>Orden PBS / Pokémon</option><option value="name" ${st.goldenSort==='name'?'selected':''}>Nombre A-Z</option><option value="powerDesc" ${st.goldenSort==='powerDesc'?'selected':''}>Potencia mayor → menor</option><option value="powerAsc" ${st.goldenSort==='powerAsc'?'selected':''}>Potencia menor → mayor</option><option value="type" ${st.goldenSort==='type'?'selected':''}>Tipo A-Z</option></select></div></div><div class="gss-summary"><div class="gss-metric"><small>Golden Moves</small><b>${total}</b><span>guardados</span></div><div class="gss-metric"><small>Visibles</small><b>${rows.length}</b><span>con filtros actuales</span></div><div class="gss-metric"><small>Tipos usados</small><b>${new Set(rows.map(r=>r.type).filter(Boolean)).size}</b><span>en esta vista</span></div><div class="gss-metric"><small>Orden</small><b>${esc(st.goldenSort)}</b><span>catálogo global</span></div></div>${rows.length?`<div class="gss-catalog-grid">${rows.map(r=>{const acc=r.cfg.accuracy??r.md?.accuracy??'—',effect=[r.cfg.functionCode?`FC: ${r.cfg.functionCode}`:'',r.cfg.effect?`Handler: ${r.cfg.effect}`:''].filter(Boolean).join(' + ')||'—',desc=String(r.cfg.description||'').trim(),origin=r.entry?displayName(r.entry):r.species;return`<article class="gss-golden-card" data-grow="${esc(r.key)}" title="Abrir ${esc(r.name)} en Golden Moves"><div class="gss-golden-visual" data-gmon="${esc(r.key)}"><div class="gss-empty">Pokémon</div></div><div class="gss-golden-card-top"><span class="gss-type-badge">${esc(r.type||'—')}</span><span class="gss-badge gold">✦ Áureo</span><div class="gss-golden-card-power">${r.power||'—'}<small>POTENCIA</small></div></div><h3>${esc(r.name)}</h3><div class="base">${esc(r.md?.name||r.move)} · ${esc(r.move)}</div><div class="gss-golden-card-species">${esc(origin)}${r.sourceForm?` · origen F${r.sourceForm}`:' · forma base'}</div><div class="gss-golden-card-meta"><div><small>Precisión</small><b>${esc(acc)}</b></div><div><small>Forma destino</small><b>${r.cfg.form!==undefined&&r.cfg.form!==null&&r.cfg.form!==''?`F${esc(r.cfg.form)}`:'—'}</b></div><div><small>Effect</small><b>${esc(effect)}</b></div></div>${desc?`<div class="gss-golden-card-desc">${esc(desc)}</div>`:''}</article>`;}).join('')}</div>`:`<div class="gss-catalog-empty"><b>No hay Golden Moves que coincidan.</b><div style="margin-top:5px">Créalo desde Golden Moves o cambia los filtros de esta biblioteca.</div></div>`}`;
