    body.querySelector('[data-gtype]').onchange=ev=>{st.goldenType=upper(ev.target.value);drawMoveCatalog();};
    body.querySelector('[data-gsort]').onchange=ev=>{st.goldenSort=String(ev.target.value||'pokemon');drawMoveCatalog();};
